#include <stdio.h>

#include <stdbool.h>
#include <stddef.h>

typedef struct node
{
    int number;
    struct node *left;
    struct node *right;
}
node;

int steps = 0;

bool search(node *tree, int number)
{
    steps++;
    if (tree == NULL)
    {
        return false;
    }
    else if (number < tree->number)
    {
        return search(tree->left, number);
    }
    else if (number > tree->number)
    {
        return search(tree->right, number);
    }
    else
    {
        return true;
    }
}

int main(void)
{
    node one = {1, NULL, NULL};
    node three = {3, NULL, NULL};
    node two = {2, &one, &three};
    bool found = search(&two, 3);
    printf("%i %i\n", found, steps);
}

